INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(298521, 21349, 7885, '<td valign="top">Good use of soft focus.</td>', 'Good use of soft focus.', '2003-05-14 23:09:59.000000', NULL, 1),
(298524, 20954, 7743, '<td valign="top">Nice focus on the central part of the flower.  For exposure, some of the petals seem overexposed.  For composition I think this image would work better is some of the fern was cropped on the right.  This would work since the main subject is the centre of the flower and not the entire flower (IMO).</td>', 'Nice focus on the central part of the flower.  For exposure, some of the petals seem overexposed.  For composition I think this image would work better is some of the fern was cropped on the right.  This would work since the main subject is the centre of the flower and not the entire flower (IMO).', '2003-05-14 23:13:34.000000', NULL, 1),
(298526, 21263, 7778, '<td valign="top">Potentially great shot with the expanse and wild texture of the shore runner, but the cobalt looks like an Exxon cover-up. :-)<br/></td>', 'Potentially great shot with the expanse and wild texture of the shore runner, but the cobalt looks like an Exxon cover-up. :-)', '2003-05-14 23:14:53.000000', NULL, 1),
(298527, 21469, 7743, '<td valign="top">Nice sharp macro and well exposed.  I think for impact though the image should be cropped more on the left and on the bottom.  It''s too central IMO.  You might even try isolating one of the orange areas, for example the one on the bottom.</td>', 'Nice sharp macro and well exposed.  I think for impact though the image should be cropped more on the left and on the bottom.  It''s too central IMO.  You might even try isolating one of the orange areas, for example the one on the bottom.', '2003-05-14 23:16:24.000000', NULL, 1),
(298528, 21076, 7743, '<td valign="top">Composition and exposure work for this image.  It doesn''t have a whole lot of impact for me though.  Maybe changing your vantage point or shooting at a different angle would improve the impact.</td>', 'Composition and exposure work for this image.  It doesn''t have a whole lot of impact for me though.  Maybe changing your vantage point or shooting at a different angle would improve the impact.', '2003-05-14 23:18:33.000000', NULL, 1),
(298529, 21110, 7743, '<td valign="top">The person on right side of the frame is distracting.  Cropping that part of the image out may have improved the composition.  The exposure seem right though.</td>', 'The person on right side of the frame is distracting.  Cropping that part of the image out may have improved the composition.  The exposure seem right though.', '2003-05-14 23:21:14.000000', NULL, 1),
(298532, 21320, 933, '<td valign="top">Very interesting photo!  Nice variation of an oft-used echnique on this site.  Great colors and composition.  The best yet!  10 md</td>', 'Very interesting photo!  Nice variation of an oft-used echnique on this site.  Great colors and composition.  The best yet!  10 md', '2003-05-14 23:24:43.000000', NULL, 1),
(298534, 21235, 7778, '<td valign="top">This shot would be difficult to crop, but the shadows are just too dark to reveal anything but ambiguity. The symmetry and expanse toward the horizon, however, remain worth telling.</td>', 'This shot would be difficult to crop, but the shadows are just too dark to reveal anything but ambiguity. The symmetry and expanse toward the horizon, however, remain worth telling.', '2003-05-14 23:25:56.000000', NULL, 1),
