(298834, 20995, 917, '<td valign="top">Dont drink and click, or your photos come out slanted.</td>', 'Dont drink and click, or your photos come out slanted.', '2003-05-15 08:56:47.000000', NULL, 1),
(298835, 21473, 8522, '<td valign="top">Incredibly vibrant and beautifully photographed. I''m not fully comfortable though about the use of existing artwork. I like the way you brought out the textures. Nice border. 8</td>', 'Incredibly vibrant and beautifully photographed. I''m not fully comfortable though about the use of existing artwork. I like the way you brought out the textures. Nice border. 8', '2003-05-15 08:57:09.000000', NULL, 1),
(298836, 21309, 917, '<td valign="top">Nice, prefer to see less grain, but its a very peaceful photo.</td>', 'Nice, prefer to see less grain, but its a very peaceful photo.', '2003-05-15 08:57:36.000000', NULL, 1),
(298838, 21021, 5176, '<td valign="top">I  like this a lot but it would have been better if the brush matched the paint</td>', 'I  like this a lot but it would have been better if the brush matched the paint', '2003-05-15 08:58:27.000000', NULL, 1),
(298839, 21163, 917, '<td valign="top">Could use a bit more seperation between  the two flower heads.</td>', 'Could use a bit more seperation between  the two flower heads.', '2003-05-15 08:59:38.000000', NULL, 1),
(298840, 21168, 917, '<td valign="top">Too pretentious for me.  Nice setup. Plane of focus a bit to far back.</td>', 'Too pretentious for me.  Nice setup. Plane of focus a bit to far back.', '2003-05-15 09:00:54.000000', NULL, 1),
(298841, 21409, 8522, '<td valign="top">Really creative use of secondary colours. This could have worked better for me with a lighter background, with less graduation... it takes away from the foreground for me. Still one of my favourites though! 8</td>', 'Really creative use of secondary colours. This could have worked better for me with a lighter background, with less graduation... it takes away from the foreground for me. Still one of my favourites though! 8', '2003-05-15 09:00:55.000000', NULL, 1);
