(299850, 21410, 6803, '<td valign="top"></td>', '', '2003-05-16 01:17:06.000000', NULL, 1),
(299853, 21156, 6325, '<td valign="top">I think the orange is composed and exposed very well. The red and yellow are really unnecessary. But I do like the oranges.</td>', 'I think the orange is composed and exposed very well. The red and yellow are really unnecessary. But I do like the oranges.', '2003-05-16 01:22:22.000000', NULL, 1),
(299855, 21329, 6325, '<td valign="top">Beautifully done. The color and detail in the flower are excellent. The bright green and black black really set it off.</td>', 'Beautifully done. The color and detail in the flower are excellent. The bright green and black black really set it off.', '2003-05-16 01:24:42.000000', NULL, 1),
(299857, 21426, 6325, '<td valign="top">Great range of green - such a dynamic color. The use of shape is strong.</td>', 'Great range of green - such a dynamic color. The use of shape is strong.', '2003-05-16 01:28:55.000000', NULL, 1),
(299863, 21373, 6325, '<td valign="top">Lovely tulip. I think it would be stronger with an out of focus background. I usually try these shots in aperture priority and vary the aperture over a wide range to see what works best.</td>', 'Lovely tulip. I think it would be stronger with an out of focus background. I usually try these shots in aperture priority and vary the aperture over a wide range to see what works best.', '2003-05-16 01:40:59.000000', NULL, 1),
(299868, 21278, 6325, '<td valign="top">Nice soft colors. Focused very well. Intriguing. I like it.</td>', 'Nice soft colors. Focused very well. Intriguing. I like it.', '2003-05-16 01:47:00.000000', NULL, 1),
(299877, 21321, 6325, '<td valign="top">Very nice composition and execution. But... the purple from the red and blue does not come out.</td>', 'Very nice composition and execution. But... the purple from the red and blue does not come out.', '2003-05-16 02:00:26.000000', NULL, 1),
(299880, 21409, 6325, '<td valign="top">Clever and well done. Background is a little uneven and not color balanced correctly, Still an 8.</td>', 'Clever and well done. Background is a little uneven and not color balanced correctly, Still an 8.', '2003-05-16 02:03:40.000000', NULL, 1),
