INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(300866, 21472, 6870, '<td valign="top">Groovy lines. I like the lighting in this shot, too.</td>', 'Groovy lines. I like the lighting in this shot, too.', '2003-05-17 11:37:45.000000', NULL, 1),
(300867, 21303, 6870, '<td valign="top">Creative and well done!</td>', 'Creative and well done!', '2003-05-17 11:38:11.000000', NULL, 1),
(300868, 21457, 6870, '<td valign="top">The mottled background really makes this flower pop!</td>', 'The mottled background really makes this flower pop!', '2003-05-17 11:38:38.000000', NULL, 1),
(300870, 21299, 6870, '<td valign="top">I like how the lily pads are little mirrors for light, but I''d like to see their colors more, regardless. Still, I think you succeeded in what you were trying to do. This is an interesting and unique shot!</td>', 'I like how the lily pads are little mirrors for light, but I''d like to see their colors more, regardless. Still, I think you succeeded in what you were trying to do. This is an interesting and unique shot!', '2003-05-17 11:40:18.000000', NULL, 1),
(300871, 21304, 6870, '<td valign="top">Nice point of view and composition. I wish the bee were in focus.</td>', 'Nice point of view and composition. I wish the bee were in focus.', '2003-05-17 11:42:11.000000', NULL, 1),
